const { chromium } = require('playwright');
const path = require('path');
const fs = require('fs');

(async () => {
  const browser = await chromium.launch({ args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1200, height: 920 } });

  const filePath = path.resolve('/app/ocean-health-chart.html');
  await page.goto('file://' + filePath, { waitUntil: 'networkidle' });

  // Wait for Chart.js to finish rendering all four charts
  await page.waitForTimeout(2000);

  // Hide scrollbar/overflow artifacts
  await page.addStyleTag({ content: '::-webkit-scrollbar { display: none !important; } body { overflow: hidden; }' });

  await page.screenshot({
    path: '/app/output/result.png',
    type: 'png',
    fullPage: true,
  });

  await browser.close();
  console.log('PNG saved to /app/output/result.png');
})();

